import re
from html import escape

def process_email(input):
    # Validation: is this a valid email?
    if not re.match(r'^[^@]+@[^@]+\.[^@]+$', input):
        raise ValueError('Invalid email format')

    # Even valid emails need sanitization for display
    return escape(input)

